#include "spark_fast_lio.h"
#include <iostream>
#include <limits>
#include <iomanip>
struct PredictionProbe {
  using Node=spark_fast_lio::SPARKFastLIO2;
  static int failures,checks;
  static void check(const char *name,bool ok,double actual=0,double expected=0){++checks;if(!ok)++failures;std::cout<<std::setprecision(17)<<"{\"test\":\""<<name<<"\",\"pass\":"<<(ok?"true":"false")<<",\"actual\":"<<actual<<",\"expected\":"<<expected<<"}\n";}
  static sensor_msgs::msg::Imu sample(double t,double ax=0,double gz=0){sensor_msgs::msg::Imu m;m.header.stamp=rclcpp::Time((int64_t)std::llround(t*1e9));m.header.frame_id="lio_imu";m.linear_acceleration.x=ax;m.linear_acceleration.z=G_m_s2;m.angular_velocity.z=gz;return m;}
  static void init(Node &n,double speed=.05){n.high_rate_predictor_.clear();n.imu_buffer_.clear();n.last_imu_timestamp_=rclcpp::Time(0,0,RCL_ROS_TIME);n.imu_processor_->mean_acc=V3D(0,0,G_m_s2);n.imu_processor_->cov_acc.setZero();n.imu_processor_->cov_gyr.setZero();n.imu_processor_->cov_bias_acc.setZero();n.imu_processor_->cov_bias_gyr.setZero();auto s=n.kf_.get_x();s.pos=V3D::Zero();s.vel=V3D(speed,0,0);s.bg=V3D::Zero();s.ba=V3D::Zero();s.rot=Eigen::Matrix3d::Identity();s.grav.vec=V3D(0,0,-G_m_s2);n.kf_.change_x(s);}
  static void send(Node &n,const sensor_msgs::msg::Imu &m){n.imuCallback(std::make_shared<sensor_msgs::msg::Imu>(m));}
  static double position(Node &n){return n.high_rate_predictor_.filter().get_x().pos(0);}
  static void run(Node &n){
    for(int k:{0,2,12,16}){init(n);for(int i=0;i<=k;i++)send(n,sample(10.+i*.004));check(("reset_lag_"+std::to_string(k)).c_str(),n.resetHighRatePrediction(10.));send(n,sample(10.+(k+1)*.004));double expected=(k+1)*.004*.05;check(("full_time_propagated_lag_"+std::to_string(k)).c_str(),n.high_rate_predictor_.ready()&&std::abs(position(n)-expected)<1e-9,position(n),expected);check("main_KF_not_edited",std::abs(n.kf_.get_x().pos(0))<1e-15);}
    init(n);for(int i=0;i<=13;i++)send(n,sample(10.+i*.004));n.resetHighRatePrediction(10.);double once=position(n);n.resetHighRatePrediction(10.);check("repeat_correction_does_not_double_integrate",std::abs(position(n)-once)<1e-12,position(n),once);
    auto corrected=n.kf_.get_x();corrected.pos(0)=.001;n.kf_.change_x(corrected);n.resetHighRatePrediction(10.024);check("later_correction_replays_only_remaining_interval",std::abs(position(n)-.0024)<1e-9,position(n),.0024);
    init(n,0);send(n,sample(10.,.2));send(n,sample(10.004,.3));check("fractional_boundary_reset_ready",n.resetHighRatePrediction(10.002));double v=n.high_rate_predictor_.filter().get_x().vel(0);check("partial_pair_linear_acceleration",std::abs(v-.00055)<1e-9,v,.00055);auto &step=n.high_rate_predictor_.steps().at(0);check("partial_pair_exact_duration",step.end_ns-step.begin_ns>=1999999&&step.end_ns-step.begin_ns<=2000001,(step.end_ns-step.begin_ns)*1e-9,.002);
    init(n,0);send(n,sample(10.,0,.1));send(n,sample(10.004,0,.2));n.resetHighRatePrediction(10.002);auto q=n.high_rate_predictor_.filter().get_x().rot.coeffs();double yaw=2*std::atan2(q.z(),q.w());check("partial_pair_gyro_rotation",std::abs(yaw-.00035)<1e-9,yaw,.00035);
    init(n);check("no_history_cannot_reset",!n.resetHighRatePrediction(10.)&&!n.high_rate_predictor_.ready());send(n,sample(10.));check("future_correction_no_extrapolation",!n.resetHighRatePrediction(10.004)&&!n.high_rate_predictor_.ready());check("old_correction_not_bracketed",!n.resetHighRatePrediction(9.996));
    n.resetHighRatePrediction(10.);send(n,sample(10.));check("duplicate_disables_prediction",!n.high_rate_predictor_.ready());send(n,sample(10.004));check("valid_sample_alone_does_not_clear_fault",!n.high_rate_predictor_.ready());check("fresh_correction_restores_prediction",n.resetHighRatePrediction(10.004));send(n,sample(10.008));check("resume_state_time_current",n.high_rate_predictor_.time_ns()==10008000000LL);
    send(n,sample(10.002));check("backward_input_clears_old_history",!n.high_rate_predictor_.ready()&&n.high_rate_predictor_.history().size()==1);send(n,sample(10.006));check("backward_recovery_requires_new_correction",!n.high_rate_predictor_.ready());check("new_epoch_correction_can_resume",n.resetHighRatePrediction(10.006));
    init(n);send(n,sample(10.));n.resetHighRatePrediction(10.);send(n,sample(10.204));check("missing_IMU_interval_blocks_prediction",!n.high_rate_predictor_.ready());check("replay_across_missing_interval_refused",!n.resetHighRatePrediction(10.));check("correction_at_fresh_anchor_can_resume",n.resetHighRatePrediction(10.204));send(n,sample(10.208));check("gap_recovery_no_old_interval_replayed",std::abs(position(n)-.0002)<1e-9,position(n),.0002);
    init(n);send(n,sample(10.));n.resetHighRatePrediction(10.);auto bad=sample(10.004);bad.linear_acceleration.x=std::numeric_limits<double>::quiet_NaN();size_t old=n.imu_buffer_.size();send(n,bad);check("nonfinite_sensor_not_fed_into_main_KF",n.imu_buffer_.size()==old&&!n.high_rate_predictor_.ready());
    init(n);for(int i=0;i<2050;i++)send(n,sample(10.+i*.004));check("original_history_bounded",n.high_rate_predictor_.history().size()==2048);check("evicted_anchor_cannot_be_reconstructed",!n.resetHighRatePrediction(10.));
    init(n);auto first=sample(10.);send(n,first);send(n,sample(10.004));n.resetHighRatePrediction(10.002);auto retained=n.high_rate_predictor_.history().front();check("original_message_stamp_unchanged",retained.header.stamp.sec==first.header.stamp.sec&&retained.header.stamp.nanosec==first.header.stamp.nanosec&&retained.linear_acceleration.z==first.linear_acceleration.z);
    auto f=n.kf_.get_x();f.pos(0)=std::numeric_limits<double>::quiet_NaN();n.kf_.change_x(f);check("nonfinite_corrected_state_refused",!n.resetHighRatePrediction(10.004)&&!n.high_rate_predictor_.ready());
  }
};
int PredictionProbe::checks=0;int PredictionProbe::failures=0;
int main(int argc,char **argv){rclcpp::init(argc,argv);rclcpp::NodeOptions options;options.parameter_overrides({rclcpp::Parameter("common.base_frame",std::string("")),rclcpp::Parameter("common.planar_mode",false),rclcpp::Parameter("common.visualization_frame",std::string("imu"))});auto node=std::make_shared<spark_fast_lio::SPARKFastLIO2>(options);PredictionProbe::run(*node);node.reset();rclcpp::shutdown();std::cout<<"{\"checks\":"<<PredictionProbe::checks<<",\"failures\":"<<PredictionProbe::failures<<"}\n";return PredictionProbe::failures?2:0;}
